quiz.answer:
package main

import "fmt"

var count int

func visit() {
    count = count + 1
}

func main() {
    var n int
    fmt.Scan(&n)
    for i := 0; i < n; i++ {
        visit()
    }
    fmt.Println("visits:", count)
}

